package xyz.ox1de.cardash;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BlurMaskFilter;
import android.graphics.Canvas;
import android.graphics.LinearGradient;
import android.graphics.Paint;
import android.graphics.PorterDuff;
import android.graphics.RectF;
import android.graphics.Shader;
import android.graphics.Typeface;
import android.graphics.drawable.Drawable;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * The car artwork (generated by tools/cargen.py): four vector layers rasterised once into a bitmap,
 * on a background thread, so the UI thread never pays for gradients or blur.
 *   tyres -> paint (MULTIPLY-tinted greyscale, keeps the shading under any colour) -> clearcoat -> glass/lamps
 */
final class CarArt {
    private CarArt() { }

    static final int HATCH = 0, SEDAN = 1;
    static final float VW = 200f, VH = 440f;

    /** Artwork geometry needed for the light effects (viewport units, right-hand lamps). */
    static final class Spec {
        final int tyres, paint, gloss, detail, litHead, litTail;
        final float headX, headY, tailX, tailY, nose, tail, tailY0;
        Spec(int t, int p, int g, int d, int lh, int lt, float hx, float hy, float tx, float ty, float n, float tl, float ty0) {
            tyres = t; paint = p; gloss = g; detail = d; litHead = lh; litTail = lt;
            headX = hx; headY = hy; tailX = tx; tailY = ty; nose = n; tail = tl; tailY0 = ty0;
        }
    }

    /** The lit-lamp bitmaps only cover these bands of the artwork (viewport y), so they stay tiny. */
    static final float HEAD_Y0 = 22, HEAD_Y1 = 96;

    static final Spec HATCH_SPEC = new Spec(R.drawable.car_hatch_tyres, R.drawable.car_hatch_paint, R.drawable.car_hatch_gloss,
            R.drawable.car_hatch_detail, R.drawable.car_hatch_lithead, R.drawable.car_hatch_littail, 158, 46, 171, 392, 17, 423, 360);
    static final Spec SEDAN_SPEC = new Spec(R.drawable.car_sedan_tyres, R.drawable.car_sedan_paint, R.drawable.car_sedan_gloss,
            R.drawable.car_sedan_detail, R.drawable.car_sedan_lithead, R.drawable.car_sedan_littail, 158, 46, 167, 420, 17, 436, 394);

    /** A rendered car: body (with shadow) plus the switched-on headlamps and tail lamps. */
    static final class Set {
        Bitmap body, head, tail;
        int pad;
        RearSpec rear;      // rear view: which art (and its lamp / plate geometry) this set was made from
    }

    // ------------------------------------------------------------------ rear ("chase cam") view

    /**
     * Rear view uses the owner's own straight-on design (tools/rearart: cut out, made symmetric,
     * cleaned and given a glossy finish, lamps rebuilt as an off / on pair, a paint mask for other
     * colours, clearcoat reflections on their own layer), mapped into a 300 x 220 viewport, ground y = 214.
     */
    static final float RW = 300f, RH = 220f, R_GROUND = 214f;

    static final class RearSpec {
        final int base, lit, paint, gloss;            // paint = 0: no tint layer (the dark car)
        final float lampLX, lampLY, lampRX, lampRY;   // light bar ends (glow anchors)
        final float bandY0, bandY1;                   // rows covered by the lamps-on layer
        final float[] plate;                          // plate quad TL, TR, BR, BL (x, y pairs)
        RearSpec(int base, int lit, int paint, int gloss, float lx, float ly, float rx, float ry, float b0, float b1, float[] plate) {
            this.base = base; this.lit = lit; this.paint = paint; this.gloss = gloss;
            lampLX = lx; lampLY = ly; lampRX = rx; lampRY = ry; bandY0 = b0; bandY1 = b1; this.plate = plate;
        }
    }

    // numbers printed by tools/rearart/build_art.py (meta.json)
    static final RearSpec WHITE_REAR = new RearSpec(R.drawable.rear2_white_base, R.drawable.rear2_white_lit,
            R.drawable.rear2_white_paint, R.drawable.rear2_white_gloss, 53.6f, 93.7f, 246.4f, 93.7f, 79.7f, 107.6f,
            new float[]{119.5f, 157.0f, 180.5f, 157.0f, 180.5f, 173.1f, 119.5f, 173.1f});
    static final RearSpec BLACK_REAR = new RearSpec(R.drawable.rear2_black_base, R.drawable.rear2_black_lit,
            0, R.drawable.rear2_black_gloss, 54.5f, 97.0f, 245.5f, 97.0f, 84.1f, 109.7f,
            new float[]{120.4f, 158.7f, 179.6f, 158.7f, 179.6f, 174.4f, 120.4f, 174.4f});

    /** Dark paint colours use the dark car as drawn; everything else the white one (tinted unless white / silver). */
    static RearSpec rearFor(int color) { return luma(color) < 0.33f ? BLACK_REAR : WHITE_REAR; }

    static float luma(int c) {
        return (0.299f * ((c >> 16) & 255) + 0.587f * ((c >> 8) & 255) + 0.114f * (c & 255)) / 255f;
    }

    static boolean neutralLight(int c) {
        int r = (c >> 16) & 255, g = (c >> 8) & 255, b = c & 255;
        return luma(c) > 0.7f && Math.max(r, Math.max(g, b)) - Math.min(r, Math.min(g, b)) < 40;
    }

    static Bitmap decode(Context ctx, int res, float targetW) {
        android.graphics.BitmapFactory.Options o = new android.graphics.BitmapFactory.Options();
        o.inScaled = false;
        o.inPreferredConfig = Bitmap.Config.ARGB_8888;
        // assets are 750 px wide: decode at half size when the car is drawn small (less memory, same look)
        o.inSampleSize = targetW <= 360 ? 2 : 1;
        return android.graphics.BitmapFactory.decodeResource(ctx.getResources(), res, o);
    }

    /**
     * The owner's own badge on the boot lid: their chosen image (cut out, see Badges) or chrome
     * lettering they type. CarDash ships no badges or logos of its own.
     */
    static final class Badge {
        static final int NONE = 0, TEXT = 1, IMAGE = 2;
        final int mode;
        final String text;
        final Bitmap image;
        final boolean chrome;
        final int ver;      // changes whenever the badge does, so the car is re-rendered once
        Badge(int mode, String text, Bitmap image, boolean chrome, int ver) {
            this.mode = mode; this.text = text == null ? "" : text; this.image = image; this.chrome = chrome; this.ver = ver;
        }
        boolean shows() { return (mode == TEXT && !text.trim().isEmpty()) || (mode == IMAGE && image != null); }
    }

    /** Centre of the flat boot-lid panel under the light bar (viewport units), where badges sit. */
    static float badgeY(RearSpec sp) { return sp == BLACK_REAR ? 114f : 112f; }

    static final int[] CHROME = {0xFFFFFFFF, 0xFFD6DAE0, 0xFF858B94, 0xFFC8CDD4, 0xFFF4F6F8};
    static final float[] CHROME_AT = {0f, 0.42f, 0.52f, 0.64f, 1f};

    static void drawBadge(Canvas c, RearSpec sp, float s, Badge bd) {
        if (bd == null || !bd.shows()) return;
        float cx = RW / 2f * s, cy = badgeY(sp) * s;
        if (bd.mode == Badge.TEXT) {
            String text = bd.text.trim();
            Paint t = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.SUBPIXEL_TEXT_FLAG);
            t.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
            t.setLetterSpacing(0.22f);
            t.setTextAlign(Paint.Align.CENTER);
            float size = 9.6f * s, maxW = 80 * s;
            t.setTextSize(size);
            float tw = t.measureText(text);
            if (tw > maxW) { size *= maxW / tw; t.setTextSize(size); }
            Paint.FontMetrics fm = t.getFontMetrics();
            float base = cy - (fm.ascent + fm.descent) / 2f, top = base + fm.ascent * 0.72f;
            Paint shadow = new Paint(t);
            shadow.setColor(0x99000000);
            shadow.setMaskFilter(new BlurMaskFilter(Math.max(0.5f, 0.6f * s), BlurMaskFilter.Blur.NORMAL));
            c.drawText(text, cx, base + 0.55f * s, shadow);
            Paint edge = new Paint(t);
            edge.setStyle(Paint.Style.STROKE);
            edge.setStrokeWidth(Math.max(0.6f, 0.35f * s));
            edge.setColor(0x73000000);
            c.drawText(text, cx, base, edge);
            t.setShader(new LinearGradient(0, top, 0, base, CHROME, CHROME_AT, Shader.TileMode.CLAMP));
            c.drawText(text, cx, base, t);
            return;
        }
        Bitmap img = bd.image;
        float k = Math.min(42 * s / img.getWidth(), 19 * s / img.getHeight());
        float w = img.getWidth() * k, h = img.getHeight() * k;
        RectF dst = new RectF(cx - w / 2f, cy - h / 2f, cx + w / 2f, cy + h / 2f);
        // a soft shadow under the badge, from its own shape: it sits on the panel instead of floating
        Bitmap a = img.extractAlpha();
        Paint sh = new Paint(Paint.FILTER_BITMAP_FLAG | Paint.ANTI_ALIAS_FLAG);
        sh.setColor(0x8C000000);
        sh.setMaskFilter(new BlurMaskFilter(Math.max(0.5f, 0.7f * s), BlurMaskFilter.Blur.NORMAL));
        c.drawBitmap(a, null, new RectF(dst.left, dst.top + 0.6f * s, dst.right, dst.bottom + 0.6f * s), sh);
        a.recycle();
        Paint ip = new Paint(Paint.FILTER_BITMAP_FLAG | Paint.ANTI_ALIAS_FLAG);
        if (!bd.chrome) { c.drawBitmap(img, null, dst, ip); return; }
        // chrome finish: the badge's own light and dark, desaturated and brightened, under a chrome band
        android.graphics.ColorMatrix cm = new android.graphics.ColorMatrix();
        cm.setSaturation(0f);
        android.graphics.ColorMatrix lift = new android.graphics.ColorMatrix(new float[]{
                1.15f, 0, 0, 0, 22, 0, 1.15f, 0, 0, 22, 0, 0, 1.15f, 0, 22, 0, 0, 0, 1, 0});
        cm.postConcat(lift);
        ip.setColorFilter(new android.graphics.ColorMatrixColorFilter(cm));
        int sv = c.saveLayer(dst, null);
        c.drawBitmap(img, null, dst, ip);
        Paint band = new Paint();
        band.setShader(new LinearGradient(0, dst.top, 0, dst.bottom, CHROME, CHROME_AT, Shader.TileMode.CLAMP));
        band.setXfermode(new android.graphics.PorterDuffXfermode(PorterDuff.Mode.MULTIPLY)); // keeps the badge's alpha
        c.drawRect(dst, band);
        c.restoreToCount(sv);
    }

    /** Rear car: body (shadow, art, optional colour, badge, number plate) + lamps-on band. */
    static Set renderRear(Context ctx, int style, int color, float s, int pad, boolean lightBg, String plate, Badge badge) {
        RearSpec sp = rearFor(color);
        int cw = Math.max(1, Math.round(RW * s)), ch = Math.max(1, Math.round(RH * s));
        Bitmap b = Bitmap.createBitmap(cw + pad * 2, ch + pad * 2, Bitmap.Config.ARGB_8888);
        Canvas c = new Canvas(b);
        c.translate(pad, pad);
        Paint sh = new Paint(Paint.ANTI_ALIAS_FLAG);
        sh.setColor(0xB4000000);                      // on the road, day or night
        sh.setMaskFilter(new BlurMaskFilter(Math.max(1f, 9 * s), BlurMaskFilter.Blur.NORMAL));
        c.drawOval(new RectF(14 * s, (R_GROUND - 10) * s, (RW - 10) * s, (R_GROUND + 5) * s), sh);

        Paint fp = new Paint(Paint.FILTER_BITMAP_FLAG | Paint.ANTI_ALIAS_FLAG);
        RectF dst = new RectF(0, 0, cw, ch);
        Bitmap base = decode(ctx, sp.base, cw);
        c.drawBitmap(base, null, dst, fp);
        base.recycle();
        if (sp.paint != 0 && !neutralLight(color)) {
            Bitmap paint = decode(ctx, sp.paint, cw);
            Paint tp = new Paint(fp);
            tp.setColorFilter(new android.graphics.PorterDuffColorFilter(color | 0xFF000000, PorterDuff.Mode.MULTIPLY));
            c.drawBitmap(paint, null, dst, tp);
            paint.recycle();
        }
        Bitmap gloss = decode(ctx, sp.gloss, cw);             // clearcoat: over the paint, never tinted
        c.drawBitmap(gloss, null, dst, fp);
        gloss.recycle();
        drawBadge(c, sp, s, badge);
        if (plate != null && !plate.trim().isEmpty()) drawPlate(c, sp.plate, s, plate.trim());
        b.prepareToDraw();

        Set r = new Set();
        r.pad = pad;
        r.body = b;
        r.rear = sp;
        // lamps-on band: same horizontal layout as the body, rows bandY0..bandY1 only
        Bitmap lit = decode(ctx, sp.lit, cw);
        Bitmap band = Bitmap.createBitmap(cw + pad * 2, Math.max(1, Math.round((sp.bandY1 - sp.bandY0) * s)), Bitmap.Config.ARGB_8888);
        Canvas bc = new Canvas(band);
        bc.translate(pad, -sp.bandY0 * s);
        bc.drawBitmap(lit, null, dst, fp);
        lit.recycle();
        band.prepareToDraw();
        r.tail = band;
        r.head = null; // no separate high stop lamp in this design: the whole bar brightens
        return r;
    }

    /** White letters on the dark plate, laid onto the plate's quad in perspective. */
    static void drawPlate(Canvas c, float[] q, float s, String text) {
        Paint t = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.SUBPIXEL_TEXT_FLAG);
        t.setTypeface(Typeface.create("sans-serif-condensed", Typeface.BOLD));
        t.setColor(0xFFF2F4F7);
        t.setTextAlign(Paint.Align.CENTER);
        t.setLetterSpacing(0.08f);
        final float W = 400, H = 110;                       // flat plate space
        float ts = H * 0.62f;
        t.setTextSize(ts);
        float tw = t.measureText(text);
        if (tw > W * 0.86f) { ts *= W * 0.86f / tw; t.setTextSize(ts); }
        android.graphics.Matrix m = new android.graphics.Matrix();
        float[] dstPts = new float[8];
        for (int i = 0; i < 8; i++) dstPts[i] = q[i] * s;
        m.setPolyToPoly(new float[]{0, 0, W, 0, W, H, 0, H}, 0, dstPts, 0, 4);
        int sv = c.save();
        c.concat(m);
        c.drawText(text, W / 2f, H / 2f + ts * 0.36f, t);
        c.restoreToCount(sv);
    }

    static Set renderSet(Context ctx, int style, int color, float s, int pad, boolean lightBg, boolean head, boolean tail) {
        Spec sp = spec(style);
        Set r = new Set();
        r.pad = pad;
        r.body = render(ctx, style, color, s, pad, lightBg);
        if (head) r.head = renderBand(ctx, sp.litHead, s, pad, HEAD_Y0, HEAD_Y1, VW, VH);
        if (tail) r.tail = renderBand(ctx, sp.litTail, s, pad, sp.tailY0, sp.tail + 2, VW, VH);
        return r;
    }

    /** One layer, cropped to the band y0..y1 of the artwork; same horizontal layout as the body bitmap. */
    static Bitmap renderBand(Context ctx, int res, float s, int pad, float y0, float y1, float vw, float vh) {
        int cw = Math.max(1, Math.round(vw * s)), ch = Math.max(1, Math.round(vh * s));
        Bitmap b = Bitmap.createBitmap(cw + pad * 2, Math.max(1, Math.round((y1 - y0) * s)), Bitmap.Config.ARGB_8888);
        Canvas c = new Canvas(b);
        c.translate(pad, -y0 * s);
        layer(ctx, c, res, 0, cw, ch);
        b.prepareToDraw();
        return b;
    }

    static Spec spec(int style) { return style == SEDAN ? SEDAN_SPEC : HATCH_SPEC; }

    /** One low-priority thread for all car rendering (dashboard + screensaver). */
    static final ExecutorService EX = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "car-art");
        t.setPriority(Thread.MIN_PRIORITY + 1);
        return t;
    });

    /**
     * @param s   pixels per artwork unit
     * @param pad shadow margin around the artwork, in pixels (the bitmap is artwork + 2*pad)
     */
    static Bitmap render(Context ctx, int style, int color, float s, int pad, boolean lightBg) {
        Spec sp = spec(style);
        int cw = Math.max(1, Math.round(VW * s)), ch = Math.max(1, Math.round(VH * s));
        Bitmap b = Bitmap.createBitmap(cw + pad * 2, ch + pad * 2, Bitmap.Config.ARGB_8888);
        Canvas c = new Canvas(b);
        c.translate(pad, pad);

        // contact shadow: wide soft one + tight dark one under the tyres
        Paint sh = new Paint(Paint.ANTI_ALIAS_FLAG);
        sh.setColor(lightBg ? 0x40000000 : 0xB4000000);
        sh.setMaskFilter(new BlurMaskFilter(Math.max(1f, 11 * s), BlurMaskFilter.Blur.NORMAL));
        c.drawRoundRect(new RectF(16 * s, (sp.nose - 2) * s, 184 * s, (sp.tail + 4) * s), 44 * s, 44 * s, sh);
        sh.setColor(lightBg ? 0x30000000 : 0x80000000);
        sh.setMaskFilter(new BlurMaskFilter(Math.max(1f, 3 * s), BlurMaskFilter.Blur.NORMAL));
        c.drawRoundRect(new RectF(22 * s, (sp.nose + 6) * s, 178 * s, (sp.tail - 4) * s), 40 * s, 40 * s, sh);

        layer(ctx, c, sp.tyres, 0, cw, ch);
        layer(ctx, c, sp.paint, color, cw, ch);
        layer(ctx, c, sp.gloss, 0, cw, ch);
        layer(ctx, c, sp.detail, 0, cw, ch);
        b.prepareToDraw(); // upload to the GPU ahead of the first frame
        return b;
    }

    static void layer(Context ctx, Canvas c, int res, int tint, int w, int h) {
        Drawable d = ctx.getDrawable(res);
        if (d == null) return;
        d = d.mutate();
        if (tint != 0) {
            d.setTint(tint);
            d.setTintMode(PorterDuff.Mode.MULTIPLY);
        }
        d.setBounds(0, 0, w, h);
        d.draw(c);
    }
}
